Array Methods:
const numbers = [1, 2, 3, 4, 5];        // source array

// Declarative vs imperative style
// Imperative (for loop): HOW
let evens = [];
for (let i = 0; i < numbers.length; i++) {         // manual loop
  if (numbers[i] % 2 === 0) evens.push(numbers[i]); // check & collect
}

// Declarative (higher-order): WHAT
const even = numbers.filter(n => n % 2 === 0);     // filter: keep evens

// Chain them
const result = numbers
  .filter(n => n > 2)             // keep numbers > 2
  .map(n => n * 10)               // multiply each by 10
  .reduce((sum, n) => sum + n, 0); // sum all into single value

// Reduce is the most powerful
const sum = numbers.reduce((a, b) => a + b, 0);     // sum of all elements
const max = numbers.reduce((a, b) => Math.max(a, b)); // find maximum
const grouped = ['a', 'b', 'a', 'c'].reduce((acc, val) => { // build frequency map
  acc[val] = (acc[val] || 0) + 1;   // increment count for each value
  return acc;                        // return accumulator
}, {});                              // start with empty object
console.log(grouped); // { a: 2, b: 1, c: 1 }

