Memory Lifecycle:
// Memory allocation happens automatically
const user = { name: 'Doge' }; // object allocated

// Reference lost → eligible for GC
let data = { large: new Array(10000) };
data = null; // original object unreachable → GC

// Closure retains references
function createHolder() {
  const big = new Array(1000000).fill('x');
  return () => console.log(big.length); // closure keeps 'big' alive
}
const fn = createHolder(); // big array NOT garbage collected
fn(); // logs 1000000

// To free: fn = null;

// Circular references are handled by modern GC
let a = {};
let b = {};
a.ref = b;
b.ref = a; // both still reachable via globals
// But if a and b become unreachable, the circular ref is not a problem

