WeakRef & FinalizationRegistry:
// WeakRef: hold weak reference
let cache = new Map();

function getCached(key) {
    if (cache.has(key)) {
        const ref = cache.get(key);
        const value = ref.deref();
        if (value !== undefined) return value;
    }
    // Create new value
    const value = { data: key, timestamp: Date.now() };
    cache.set(key, new WeakRef(value));
    return value;
}

// FinalizationRegistry: cleanup on GC
const registry = new FinalizationRegistry((heldValue) => {
    console.log(`Object ${heldValue} was collected`);
});

function createExpensiveResource(id) {
    const resource = new Array(1000000).fill(id);
    registry.register(resource, id);  // cleanup callback
    return resource;
}

